-- ==============================================================================\n-- CLEAN_DATA TABLES\n-- ==============================================================================\n-- Initial CLEAN_DATA setup extracted from the supplied SQL.\n\nUSE DATABASE MARKETING_CAMP_ANALYSIS;\nUSE SCHEMA CLEAN_DATA;\n\n-- CUSTOMER JOURNEY CLEAN TABLE\nCREATE OR REPLACE TABLE CLEAN_DATA.CUSTOMER_JOURNEY\n(\n    JOURNEYID   NUMBER(38,0),\n    CUSTOMERID  NUMBER(38,0),\n    PRODUCTID   NUMBER(38,0),\n    VISITDATE   DATE,\n    STAGE       VARCHAR,\n    ACTION      VARCHAR,\n    DURATION    NUMBER(38,2)\n);\n\nINSERT INTO CLEAN_DATA.CUSTOMER_JOURNEY\n(JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE, STAGE, ACTION, DURATION)\nWITH CTE AS\n(SELECT JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE,\n        UPPER(TRIM(STAGE)) AS STAGE,\n        TRIM(ACTION) AS ACTION,\n        DURATION,\n        AVG(TRY_TO_NUMBER(DURATION)) OVER (PARTITION BY VISITDATE) AS AVG_DURATION,\n        ROW_NUMBER() OVER( PARTITION BY CUSTOMERID, PRODUCTID, VISITDATE, UPPER(TRIM(STAGE)), TRIM(ACTION) ORDER BY JOURNEYID) AS ROW_NUM\n FROM RAW_DATA.CUSTOMER_JOURNEY)\nSELECT JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE, STAGE, ACTION,\n       COALESCE(TRY_TO_NUMBER(DURATION), AVG_DURATION) AS DURATION\nFROM CTE WHERE ROW_NUM = 1;\n\nSELECT * FROM CLEAN_DATA.CUSTOMER_JOURNEY LIMIT 5;\nDESC TABLE CLEAN_DATA.CUSTOMER_JOURNEY;\n\n-- Other CLEAN_DATA tables were already created/loaded in the working project.\n-- Their incremental maintenance is handled by 05_tasks.sql.\n